using UnityEngine;

// Local weather is derived from the saved calendar; no internet is required.
public sealed class GridShiftWeather:MonoBehaviour {
 public static bool Raining{get;private set;}public static string Description{get;private set;}="Céu limpo";
 public int overrideWeather=-1;ParticleSystem rain;Material rainMaterial;float moisture;bool oldFog;Color oldFogColor;float oldDensity;
 void Start(){oldFog=RenderSettings.fog;oldFogColor=RenderSettings.fogColor;oldDensity=RenderSettings.fogDensity;var go=new GameObject("Rain around active exterior camera");go.transform.SetParent(transform,false);rain=go.AddComponent<ParticleSystem>();var main=rain.main;main.playOnAwake=false;main.loop=true;main.maxParticles=1400;main.startLifetime=1.1f;main.startSpeed=18;main.startSize=.035f;main.startColor=new Color(.65f,.75f,.85f,.55f);main.simulationSpace=ParticleSystemSimulationSpace.World;var emission=rain.emission;emission.rateOverTime=800;var shape=rain.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(25,25,1);go.transform.rotation=Quaternion.Euler(90,0,0);var renderer=go.GetComponent<ParticleSystemRenderer>();var template=Resources.Load<Material>("GridShiftRain20");rainMaterial=template!=null?new Material(template):new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));rainMaterial.color=new Color(.65f,.78f,.9f,.6f);renderer.sharedMaterial=rainMaterial;renderer.renderMode=ParticleSystemRenderMode.Stretch;renderer.lengthScale=6;rain.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
 public static int StateAt(double days){int block=(int)System.Math.Floor(days*6);uint x=unchecked((uint)(block*1103515245+12345));return (x>>16)%5<2?2:(x>>16)%5==2?1:0;}
 void LateUpdate(){var world=WorldSession.Instance;if(world==null||rain==null)return;int state=overrideWeather>=0?overrideWeather:StateAt(world.CalendarDays);Raining=state==2;Description=state==2?"Chuva":state==1?"Nublado":"Céu limpo";bool outside=!world.InInterior&&!world.Busy;moisture=Mathf.MoveTowards(moisture,outside?(state==2?1:state==1?.5f:0):0,Time.deltaTime*.12f);RenderSettings.fog=oldFog||moisture>.02f;RenderSettings.fogMode=FogMode.Exponential;RenderSettings.fogDensity=Mathf.Lerp(oldDensity,.012f,moisture);float hour=world.ClockHour;RenderSettings.fogColor=Color.Lerp(oldFogColor,hour<6||hour>=18?new Color(.025f,.04f,.07f):new Color(.4f,.47f,.54f),moisture);var camera=Camera.main;if(camera!=null){rain.transform.position=camera.transform.position+Vector3.up*12;if(Raining&&outside){if(!rain.isPlaying)rain.Play();}else if(rain.isPlaying)rain.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}}
 void OnDestroy(){Raining=false;RenderSettings.fog=oldFog;RenderSettings.fogColor=oldFogColor;RenderSettings.fogDensity=oldDensity;if(rainMaterial!=null)Destroy(rainMaterial);}
}

